import {createIcons,Shield,Map,BookOpen,ScrollText,ChevronDown,CircleHelp,Ribbon,Shirt,Footprints,Crown,Swords,Check,Lock,Sparkles,Volume2,VolumeX,Flag,Gem,Sword,Dices,ArrowRight,Activity,ArrowUpRight,ShieldCheck,X,CheckCheck,Coins,Lamp,Flame,Store,CloudLightning,Heart,Zap,Snowflake,Droplets,HeartPulse,Wind,Crosshair} from 'lucide';
const icons={Shield,Map,BookOpen,ScrollText,ChevronDown,CircleHelp,Ribbon,Shirt,Footprints,Crown,Swords,Check,Lock,Sparkles,Volume2,VolumeX,Flag,Gem,Sword,Dices,ArrowRight,Activity,ArrowUpRight,ShieldCheck,X,CheckCheck,Coins,Lamp,Flame,Store,CloudLightning,Heart,Zap,Snowflake,Droplets,HeartPulse,Wind,Crosshair};
