const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<i data-lucide="${name}" class="${cls}" aria-hidden="true"></i>`;
let welcome=true;
let state=freshState(),user=null,revision=0,guest=false,busy=false,syncIssue=false,saveChain=Promise.resolve(),lastFocus=null,practice=null;
const tileIcons=['flag','book-open','sparkles','scroll-text','book-open','gem','scroll-text','sparkles','book-open','scroll-text','gem','book-open','sparkles','scroll-text','book-open','gem','scroll-text','sparkles','book-open','crown'];

function monsterPortrait(id,cls=''){const m=monsterInfo(id);return `<div class="monster-art ${cls}" role="img" aria-label="${esc(m.name)}" style="background-image:url('${import.meta.env.BASE_URL}monsters-atlas.png');background-position:${m.cell%6*20}% ${Math.floor(m.cell/6)*100/3}%"></div>`;}
function showBestiary(){modal(`<button class="close" data-close aria-label="Close creatures">${icon('x')}</button><div class="eyebrow gold">CREATURES OF THE QUEST</div><h2 id="dialog-title">The monster collection</h2><p>24 mythical foes. Encounters rotate without repeats until you have met the full roster. Chapter bosses guard each final tile.</p><div class="bestiary-grid">${MONSTERS.map(m=>`<article>${monsterPortrait(m.id)}<h3>${m.name}</h3></article>`).join('')}</div>`,true);}
function heroAsset(character=state.character){return import.meta.env.BASE_URL+(character==='female'?'hero-female.png':'hero.png');}
function characterPicker(selected='male'){return `<fieldset class="character-picker"><legend>Choose your character</legend><div>${['male','female'].map(c=>`<label class="character-option"><input type="radio" name="character" value="${c}" ${c===selected?'checked':''}><span><img src="${heroAsset(c)}" alt=""><strong>${c==='male'?'Male':'Female'} adventurer</strong></span></label>`).join('')}</div><small>Same abilities. Your adventure, your hero.</small></fieldset>`;}
let journeyTimer;
let boardMotion=null;
let sound=true,battleAnimating=false,battlePaused=false,battleSpeed=1,battleTimer;
function chime(success=true){questAudio.effect(success);}
function scheduleBattle(){clearTimeout(battleTimer);if(welcome||battlePaused||battleAnimating||syncIssue||!state.battle||!state.battle.started||state.battle.done||!$('.battle-arena')||$('#overlay').children.length||document.hidden)return;battleTimer=setTimeout(()=>{if(battlePaused||!$('.battle-arena'))return;const action=state.battle.intent==='heavy'?'guard':(state.run.charge||0)>=100?'radiance':'strike';animateCombat(action);},650/battleSpeed);}
document.addEventListener('visibilitychange',()=>{if(document.hidden){clearTimeout(journeyTimer);clearTimeout(battleTimer);questAudio.hush();}else{questAudio.start();scheduleBattle();scheduleJourney();}});
document.addEventListener('pointerdown',()=>{questAudio.start();},{once:true});
document.addEventListener('keydown',()=>{questAudio.start();},{once:true});
function iconsNow(){createIcons({icons,attrs:{'stroke-width':1.65}});}
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function closeModal(){if(battleAnimating)return;clearTimeout(battleTimer);questAudio.mode='board'; $('#overlay').innerHTML='';document.body.classList.remove('modal-open');lastFocus?.focus?.();scheduleJourney();if(!welcome&&state.battle){questAudio.mode='battle';if(state.battle.done)battleTimer=setTimeout(completeBattle,1000);else scheduleBattle();}}
function modal(html,wide=false){clearTimeout(journeyTimer);clearTimeout(battleTimer);questAudio.mode='board';lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="veil"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title">${html}</section></div>`;document.body.classList.add('modal-open');iconsNow();setTimeout(()=>($('.modal input:not([disabled]), .modal textarea')||$('.modal button:not([disabled])'))?.focus(),40);}
document.addEventListener('keydown',e=>{const dialog=$('.modal');if(!dialog)return;if(e.key==='Escape'&&$('[data-close]'))closeModal();if(e.key==='Tab'){const a=[...dialog.querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea,a[href]')].filter(x=>x.offsetParent!==null);if(!a.length)return;const f=a[0],l=a.at(-1);if(e.shiftKey&&document.activeElement===f){e.preventDefault();l.focus();}else if(!e.shiftKey&&document.activeElement===l){e.preventDefault();f.focus();}}});
document.addEventListener('click',e=>{if(e.target.closest('[data-close]'))closeModal();});
function syncLabel(text){const el=$('#sync');if(el)el.textContent=text;}
function persist(){
 if(guest){try{localStorage.setItem('armorQuestPracticeV2',JSON.stringify(state));}catch{notify('This browser could not save practice progress. Keep this tab open.');}syncLabel('Practice · saved on this device');return Promise.resolve();}
 if(!user)return Promise.resolve();
 const snapshot=structuredClone(state);syncLabel('Saving progress…');
 saveChain=saveChain.then(async()=>{if(syncIssue)return;try{revision=await saveProgress(snapshot,revision);syncLabel('Progress saved online');}catch(e){syncIssue=true;syncLabel('Save interrupted · tap to resolve');notify(e.message||'Could not save. Your quest is still open on this device.');render();}});
 return saveChain;
}
function render(){
 if(welcome){renderWelcome();return;}
 document.body.dataset.phase=state.phase==='run'?'run':'lobby';document.body.dataset.chapter=state.stage;
 if(state.phase!=='run'){renderLobby();return;}
 const s=STAGES[state.stage],stats=summary(state),name=state.alias||state.name||'Adventurer';
 $('#app').innerHTML=`<header class="topbar"><a href="./" class="brand" aria-label="Bible Flashcard Game home"><span class="brand-emblem">${icon('shield')}</span><span>THE ARMOR QUEST<small>BIBLE FLASHCARD GAME</small></span></a><nav aria-label="Main navigation"><button class="nav-active" id="questNav" aria-label="Quest board">${icon('map')}<span>Quest board</span></button><button id="versesNav" aria-label="Verse library">${icon('book-open')}<span>Verse library</span></button><button id="resultsNav" aria-label="My results">${icon('scroll-text')}<span>My results</span></button></nav><button class="profile" id="profile" aria-label="Your adventurer profile"><span class="avatar">${esc(name.slice(0,1).toUpperCase())}</span><span>${user||guest?esc(name):'Join the quest'}<small>${user?'ONLINE ADVENTURER':guest?'PRACTICE ADVENTURER':'CREATE YOUR HERO'}</small></span>${icon('chevron-down')}</button></header>
 <main><div class="quest-heading"><div><div class="eyebrow"><span class="mini-line"></span>THE GOSPEL OF JOHN · CHAPTERS 1–4</div><h1>Your faith. Your adventure.</h1><p>Follow the path. Know the Word. Put on the armor.</p></div><button class="quiet help-button" id="help">${icon('circle-help')} How to play</button></div>
 <div class="game-layout"><aside class="journey panel"><div class="panel-label">YOUR JOURNEY <span>0${Math.min(state.armor.length+1,6)} / 06</span></div><h2>The armor awaits.</h2><p class="muted">Six trials of faith. One complete armor.</p><div class="stage-list">${STAGES.map((a,i)=>`<button class="stage ${i===state.stage?'active':''} ${state.armor.includes(i)?'earned':''}" data-stage="${i}"><span class="stage-symbol">${icon(state.armor.includes(i)?'check':i>state.stage?'lock':a.icon)}</span><span><small>CHAPTER ${String(i+1).padStart(2,'0')}</small><strong>${a.name}</strong><span class="stage-reward">${a.armor}</span></span>${i===state.stage?'<span class="current-dot"></span>':''}</button>`).join('')}</div><div class="journey-footer">${icon('sparkles')}<span>“Be strong in the Lord.”<small>EPHESIANS 6:10</small></span></div></aside>
 <section class="board-panel" aria-label="Interactive quest board"><div class="board-top"><div><div class="eyebrow">CHAPTER ${String(state.stage+1).padStart(2,'0')} <span class="tag">${state.run.total-state.run.turn} TURNS LEFT</span></div><h2>${s.name}</h2><span>${s.region}</span></div><button class="icon-button" id="sound" aria-label="${sound?'Mute':'Enable'} music and sounds" aria-pressed="${sound}">${icon(sound?'volume-2':'volume-x')}</button></div><div class="board-scene" style="background-image:url('${import.meta.env.BASE_URL+MAPS[state.stage].art}')" aria-label="${MAPS[state.stage].name} map"><div class="board-shade"></div><div class="board-path" aria-label="20 board spaces"><svg class="circuit-track" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><polygon points="${MAPS[state.stage].path.map(p=>p.join(',')).join(' ')}"/></svg><div class="board-monument">${icon(STAGES[state.stage].icon)}<strong>${MAPS[state.stage].name}</strong><small>LAP ${(state.run.lap||0)+1}</small></div>${MAPS[state.stage].path.map(([x,y],i)=>`<button class="tile tile-${tileType(state,i)} ${i===state.position?'occupied':''} ${i%5===0?'corner':''} " style="--x:${x}%;--y:${y}%" data-tile="${i}" aria-label="Space ${i+1}: ${i===state.position?'your hero':EVENTS[tileType(state,i)]?.name||'verse trial'}"><span>${icon(EVENTS[tileType(state,i)]?.icon||tileIcons[i])}</span><small>${i%5===0?({camp:'REST',market:'SHOP',treasure:'CHEST',blessing:'LIGHT',trial:'VERSE',elite:'ELITE',boss:'BOSS',battle:'FIGHT',storm:'STORM'}[tileType(state,i)]):i+1}</small><em class="step-number"></em></button>`).join('')}<div class="hero-token" style="--x:${MAPS[state.stage].path[state.position][0]}%;--y:${MAPS[state.stage].path[state.position][1]}%" aria-label="Your hero's position"><img src="${heroAsset()}" alt=""><span></span></div></div><div class="supplies"><span class="health-supply" title="Hero health">${icon('heart')} ${state.health}</span><span title="Ultimate charge">${icon('zap')} ${state.run.charge||0}%</span><span>${icon('coins')} ${state.tokens||0} tokens</span><span>${icon('lamp')} ${state.lanterns||0}</span><span>${icon('shield-check')} ${state.wards||0}</span></div><div class="boss-countdown"><span>${icon('crown')} ${30-state.run.turn} rolls to boss</span><div><b style="width:${state.run.turn/30*100}%"></b></div></div><div class="map-label">${state.run.turn===30?'FINAL BOSS':'LAP '+((state.run.lap||0)+1)+' · AUTOMATIC JOURNEY'}</div><div class="board-legend"><span>${icon('swords')} Fight</span><span>${icon('book-open')} Verse</span><span>${icon('gem')} Treasure</span><span>${icon('store')} Market</span><span>${icon('cloud-lightning')} Storm</span></div></div><div class="board-controls"><div class="dice" aria-label="Last die roll ${state.lastRoll||'not rolled'}">${state.lastRoll||icon('dices')}</div><div class="roll-caption"><strong>${state.complete?'The armor is yours.':state.ended?'Your journey is paused.':state.pending||state.event||state.upgradePending||state.battle?'An encounter awaits.':state.run.paused?'Journey paused.':'Your hero travels automatically.'}</strong><span>${state.complete?'Every piece earned. Keep the Word close.':state.pending?'Answer the challenge on your tile.':'Choices pause the journey. Defeat ends the run.'}</span></div><button class="primary roll" id="roll" ${busy||syncIssue?'disabled':''}>${icon(state.pending?'book-open':'dices')}${state.complete||state.ended?'View results':state.pending||state.event||state.upgradePending||state.battle?'Continue encounter':user||guest?state.run.paused?'Resume journey':'Pause journey':'Begin your quest'}${icon('arrow-right')}</button></div></section>
 <aside class="right-rail"><section class="panel reward"><div class="panel-label">NEXT ARMOR PIECE ${icon('sparkles')}</div><div class="armor-display">${icon(s.icon)}<div class="orbit"></div></div><span class="eyebrow gold">${state.complete?'COLLECTION COMPLETE':'EARN YOUR ARMOR'}</span><h2>${state.complete?'The full Armor of God':s.armor}</h2><p>${s.verse}</p><div class="progress-label"><span>Correct answers</span><b>${Math.min(state.stageCorrect,4)} / 4</b></div><div class="progress-bar"><span style="width:${Math.min(state.stageCorrect/4,1)*100}%"></span></div><div class="trial-count">Win this chapter with 4 correct answers<br>${state.stageAttempts} verse trials answered</div><div class="armor-inventory" aria-label="Armor inventory">${STAGES.map((a,i)=>`<span title="${a.armor}: ${state.armor.includes(i)?'earned':'locked'}" class="${state.armor.includes(i)?'unlocked':''}">${icon(a.icon)}</span>`).join('')}</div></section><section class="panel score-panel"><div class="panel-label">THIS ADVENTURE ${icon('activity')}</div><div class="score-row"><div><b>${stats.right}</b><span><em class="good">●</em> Correct</span></div><div><b>${stats.wrong}</b><span><em class="bad">●</em> To review</span></div></div><button class="text-button" id="review">Review my verses ${icon('arrow-up-right')}</button></section><button class="build-button armory-button" id="armory">${icon('shirt')} Armory & hero <b>LV ${career(state).level}</b></button><button class="build-button" id="mySkills">${icon('sparkles')} My skills <b>${Object.keys(state.skills||{}).length}</b></button><button class="sync" id="sync">${guest?'Practice · saved on this device':user?(syncIssue?'Save interrupted · tap to resolve':'Progress saved online'):'Sign in to save across devices'}</button></aside></div>
 <footer><span>${icon('shield-check')} ARMOR OF GOD · EPHESIANS 6:10–17</span><span>${data.questions.length} questions · ${data.verses.length} memory passages · Your supplied John 1–4 study sets</span></footer></main>`;
 iconsNow();
 $('#roll').onclick=()=>state.complete||state.ended?showResults():state.battle?showBattle():state.upgradePending?showUpgrade():state.event?showEncounter():state.pending?showChallenge():!user&&!guest?showAuth():toggleJourney();
 $('#profile').onclick=()=>user||guest?showProfile():showAuth();$('#questNav').onclick=()=>{closeModal();continueRun();};$('#versesNav').onclick=showLibrary;$('#resultsNav').onclick=showResults;$('#review').onclick=showResults;$('#help').onclick=showHelp;
 $('#armory').onclick=()=>notify('Your equipment is locked for this run. Upgrade in the lobby after victory or defeat.');$('#mySkills').onclick=showSkills;$('#sound').onclick=()=>{sound=!sound;questAudio.enabled=sound;questAudio.start();render();};
 $('#sync').onclick=()=>syncIssue?showSyncIssue():!user?showAuth():notify('Your quest saves after every roll and answer.');
 document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.stage);notify(n===state.stage?'This is your current run. Your hero moves automatically.':state.armor.includes(n)?`${STAGES[n].armor} earned. Review your verses in My results.`:'Finish the current chapter to unlock this path.');});
 document.querySelectorAll('[data-tile]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.tile)===state.position&&state.pending)showChallenge();else notify(EVENTS[tileType(state,Number(b.dataset.tile))]?.description||'Your hero moves automatically; encounters pause for choices.');});
 const tools=document.createElement('div');tools.className='run-tools';tools.innerHTML=`<span>${stats.right} correct · ${stats.wrong} review</span>`;$('.board-top').after(tools);for(const id of ['mySkills','review','help'])tools.append($('#'+id));const bestiary=document.createElement('button');bestiary.textContent='Monsters';bestiary.onclick=showBestiary;tools.append(bestiary);
 if(state.battle&&!$('#overlay').children.length&&!battleAnimating)showBattle();
 if(busy){document.querySelectorAll('.topbar button,.run-tools button,[data-tile]').forEach(b=>b.disabled=true);}
 if(boardMotion)drawBoardRoll();
 scheduleJourney();
}
function showAuth(tab='signup'){
 modal(`<button class="close" data-close aria-label="Close">${icon('x')}</button><div class="modal-emblem">${icon('shield')}</div><div class="eyebrow gold">YOUR STORY STARTS HERE</div><h2 id="dialog-title">${tab==='signup'?'Become an adventurer.':'Welcome back, adventurer.'}</h2><p class="muted">Create your hero and carry your progress from one device to the next.</p><div class="tabs"><button id="signupTab" class="${tab==='signup'?'selected':''}">Create account</button><button id="loginTab" class="${tab==='login'?'selected':''}">Sign in</button></div>${!configured?'<div class="notice">Online accounts are awaiting the site owner’s connection. You can explore the complete game in practice mode below.</div>':''}<form id="authForm">${tab==='signup'?'<div class="field-row"><label>Your name<input name="name" autocomplete="given-name" maxlength="40" required placeholder="First name"></label><label>Hero alias <span>(optional)</span><input name="alias" autocomplete="nickname" maxlength="30" placeholder="Lightbearer"></label></div>':''}${tab==='signup'?characterPicker():''}<label>Email<input name="email" type="email" autocomplete="email" required placeholder="you@example.com"></label><label>Password<input name="password" type="password" autocomplete="${tab==='signup'?'new-password':'current-password'}" minlength="8" required placeholder="At least 8 characters"></label><p id="authError" class="form-message" role="status"></p><button class="primary full" ${!configured?'disabled':''}>${tab==='signup'?'Create account':'Sign in & resume'} ${icon('arrow-right')}</button></form><button class="text-button full" id="practice">Explore in practice mode</button><p class="fine">Practice saves on this device. Online accounts use your email and password; your hero displays your alias or first name.</p>`);
 $('#signupTab').onclick=()=>showAuth('signup');$('#loginTab').onclick=()=>showAuth('login');
 $('#practice').onclick=()=>showPracticeSetup();
 $('#authForm').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),btn=e.target.querySelector('button');btn.disabled=true;$('#authError').textContent='Connecting…';try{const result=tab==='signup'?await signUp(form.get('email'),form.get('password'),form.get('name').trim(),form.get('alias').trim(),form.get('character')):await signIn(form.get('email'),form.get('password'));if(!result.session){$('#authError').textContent='Check your email to confirm your account, then come back and sign in.';btn.disabled=false;return;}await enterAccount(result.session.user);welcome=false;closeModal();render();if(state.phase==='run')continueRun();}catch(err){$('#authError').textContent=err.message;btn.disabled=false;}};
}
function showPracticeSetup(){modal(`<button class="close" data-close aria-label="Close">${icon('x')}</button><div class="eyebrow gold">PRACTICE ADVENTURE</div><h2 id="dialog-title">Choose your hero.</h2><p class="muted">Start at level 1 with a new hero. Your new game replaces the saved game on this device when you press Enter the quest.</p><form id="practiceForm">${characterPicker()}<label>Your name<input name="name" maxlength="40" required placeholder="First name"></label><label>Hero alias (optional)<input name="alias" maxlength="30" placeholder="Lightbearer"></label><label>Challenge style<select name="mode">${Object.entries(MODES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><button class="primary full">Enter the quest ${icon('arrow-right')}</button></form>`);$('#practiceForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);welcome=false;user=null;guest=true;state=freshState(f.get('name').trim(),f.get('alias').trim(),f.get('mode'),f.get('character'));persist();closeModal();render();};}
async function enterAccount(account){user=account;guest=false;const saved=await loadProgress();revision=saved?.revision||0;state={...freshState(account.user_metadata?.name||'Adventurer',account.user_metadata?.alias||'','mixed',account.user_metadata?.character||'male'),...(saved?.state||{})};state=migrate(state);syncIssue=false;if(!saved)await persist();}
const pauseFor=ms=>new Promise(r=>setTimeout(r,ms));
function diceCube(value){return `<div class="dice-cube face-${value}">${[1,2,3,4,5,6].map(n=>`<span class="cube-face side-${n}">${Array.from({length:9},(_,i)=>`<b class="${({1:[4],2:[0,8],3:[0,4,8],4:[0,2,6,8],5:[0,2,4,6,8],6:[0,2,3,5,6,8]}[n]).includes(i)?'pip':'pip-off'}"></b>`).join('')}</span>`).join('')}</div>`;}
function drawBoardRoll(){
 if(!boardMotion||!$('.board-scene'))return;
 const {phase,dice,steps}=boardMotion;
 $('.roll-theater')?.remove();
 $('.board-scene').insertAdjacentHTML('beforeend',`<div class="roll-theater ${phase}" role="status" aria-live="polite"><div class="roll-glow"></div><span class="roll-kicker">${phase==='rolling'?'ROLLING THE DICE':phase==='moving'?'FOLLOW THE PATH':'YOUR ROLL'}</span><div class="dice-pair">${dice.map(diceCube).join('')}</div><strong class="roll-total">${phase==='rolling'?'':steps}</strong><span class="roll-message">${phase==='rolling'?'Your next encounter awaits':phase==='moving'?steps+' spaces to travel':dice.join(' + ')+' = '+steps+' spaces'}</span></div>`);
}
async function roll(){
 if(welcome||busy||syncIssue||state.phase!=='run'||state.run.paused||state.pending||state.event||state.upgradePending||state.battle)return;
 busy=true;state=planMove(state);const id=state.run.id,move=state.run.move,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const valid=()=>!welcome&&state.phase==='run'&&state.run.id===id;
 const dice=move.dice||[Math.min(6,move.steps),0];
 boardMotion={phase:'rolling',dice:dice.filter(Boolean),steps:move.steps};persist();render();
 if(!reduced){questAudio.rollEffect?.();await pauseFor(1000);}
 if(!valid()){busy=false;boardMotion=null;return;}
 boardMotion.phase='result';drawBoardRoll();await pauseFor(reduced?250:700);
 boardMotion.phase='moving';drawBoardRoll();
 const path=movePath(move.from,move.steps);
 path.forEach((pos,i)=>{const tile=$(`[data-tile="${pos}"]`);tile?.classList.add('upcoming');if(tile)tile.querySelector('.step-number').textContent=i+1;});
 for(let i=0;i<path.length;i++){
  if(!valid()){busy=false;boardMotion=null;return;}
  const position=path[i],[x,y]=MAPS[state.stage].path[position];state.position=position;
  document.querySelectorAll('.tile.occupied').forEach(t=>t.classList.remove('occupied'));
  const tile=$(`[data-tile="${position}"]`);tile?.classList.add('occupied','stepped');tile?.classList.remove('upcoming');
  const token=$('.hero-token');token?.style.setProperty('--x',x+'%');token?.style.setProperty('--y',y+'%');
  if(!reduced){token?.querySelector('img')?.animate([{transform:'translateY(0)'},{transform:'translateY(-16px)'},{transform:'translateY(0)'}],{duration:280});questAudio.stepEffect?.();}
  const message=$('.roll-message');if(message)message.textContent=`${i+1} / ${move.steps} spaces`;
  await pauseFor(reduced?25:320);
 }
 $('.roll-theater')?.remove();$(`[data-tile="${move.to}"]`)?.classList.add('landed');
 const scene=$('.board-scene');scene?.insertAdjacentHTML('beforeend',`<div class="landing-banner" role="status">${icon(EVENTS[move.kind]?.icon||'book-open')} ${move.kind==='trial'?'Bible verse trial':EVENTS[move.kind]?.name||'Encounter'}${move.lap>(state.run.lap||0)?'<small>NEW LAP · THE BOARD REFRESHES</small>':''}</div>`);iconsNow();
 await pauseFor(reduced?200:800);
 if(!valid()){busy=false;boardMotion=null;return;}
 state=arrive(state);busy=false;boardMotion=null;const kind=state.event;
 if(['battle','elite','boss'].includes(kind)){battlePaused=false;state=startBattle(state,kind);persist();render();}
 else if(kind==='trial')beginTrial();else{if(kind==='market')state=enterShop(state);persist();render();showEncounter();}
}
function showChallenge(){
 if(state.feedback){showFeedback();return;}const q=state.pending;if(!q)return;const labels={blank:'RESTORE THE WORD',reference:'NAME THE REFERENCE',recall:'RECALL THE VERSE',quiz:'KNOW THE SCRIPTURE'};
 modal(`<button class="close" data-close aria-label="Return to board">${icon('x')}</button><div class="trial-heading"><span class="trial-badge">${icon(q.mode==='reference'?'scroll-text':q.mode==='recall'?'swords':'book-open')}</span><span class="eyebrow gold">${q.boss?'MASTERY GATE · FINAL TRIAL':labels[q.mode]}<small>CHAPTER ${state.stage+1} · TRIAL ${state.stageAttempts+1}</small></span></div><h2 id="dialog-title">${q.boss?'The final trial of this chapter.':q.mode==='blank'?'Complete the missing word.':q.mode==='reference'?'Where is this verse found?':q.mode==='recall'?'Let the Word come to mind.':'A challenge on your path.'}</h2><div class="verse-card"><blockquote>${esc(q.prompt)}</blockquote>${q.mode==='blank'?`<cite>${esc(q.reference)}</cite>`:''}</div><form id="answerForm"><label>${q.mode==='reference'?'Verse reference':q.mode==='recall'?'Type the complete verse':q.mode==='blank'?'Type the complete missing word':'Your answer'}${q.mode==='recall'?'<textarea name="answer" rows="5" placeholder="Write the verse here…" required></textarea>':`<input name="answer" autocomplete="off" spellcheck="false" required placeholder="${q.mode==='reference'?'e.g. John 1:14':q.mode==='blank'?esc(q.mask):'Your answer…'}">`}</label><p class="fine">${q.mode==='reference'?'Include the chapter and verse; include a range for a multi-verse passage.':'Capitalization and punctuation don’t count. Match the wording in your study set.'}</p><button class="primary full">Check my answer ${icon('arrow-right')}</button></form>${!q.boss?`<button id="useHint" class="quiet full" ${state.lanterns<1||q.assisted?'disabled':''}>${icon('lamp')} Use a lantern · ${state.lanterns} left</button><p id="hintText" class="hint-text">${q.assisted?esc(getHint(q)):''}</p>`:'<p class="fine">The mastery gate must be passed without a lantern.</p>'}<button id="skip" class="text-button full">I don’t know yet · show answer</button>`);
 $('#answerForm').onsubmit=e=>{e.preventDefault();answer(new FormData(e.target).get('answer'));};$('#skip').onclick=()=>answer('');$('#useHint')?.addEventListener('click',()=>{if(state.lanterns<1||q.assisted)return;state.lanterns--;state.pending.assisted=true;persist();$('#hintText').textContent=getHint(q);$('#useHint').disabled=true;$('#useHint').textContent='Lantern used';});
}
function answer(input){if(syncIssue){showSyncIssue();return;}if(!state.pending||state.feedback)return;state=recordAnswer(state,input);persist();render();chime(state.feedback.correct);showFeedback();}
function beginTrial(boss=false){state.event=null;state.pending=makeChallenge(data,state.stage,boss?'reference':state.mode,state.seen);state.pending.boss=boss;state.feedback=null;persist();render();showChallenge();}
function showBattle(){
 const b=state.battle;if(!b)return;battlePaused=Boolean(state.run.battlePaused);$('.battle-dock')?.remove();
 const dock=document.createElement('section');dock.className='battle-dock';dock.setAttribute('aria-label','Battle encounter');
 dock.innerHTML=`<div class="battle-heading"><span class="eyebrow gold">${b.done?'BATTLE COMPLETE':!b.started?'ENEMY ENCOUNTER':'ROUND '+b.turn}</span><h2>${b.name}</h2></div>
 <div class="combat-stats"><div><strong>${esc(state.alias||state.name)}</strong><span>${state.health} / ${maxHealth(state)} HP</span><div class="health-bar"><b style="width:${state.health/maxHealth(state)*100}%"></b></div></div><div><strong>${b.name}</strong><span>${b.hp} / ${b.max} HP</span><div class="health-bar enemy"><b style="width:${b.hp/b.max*100}%"></b></div></div></div>
 <div class="ultimate-status"><span>${weaponAbility(career(state).equipped.sword).name} <b>${state.run.charge||0}%</b></span><span class="shield-readout">${icon('shield')} ${b.shield||0} shield HP</span><div class="progress-bar"><span style="width:${state.run.charge||0}%"></span></div></div>
 <div class="battle-arena ${b.done?'battle-'+b.outcome:''}"><img class="fighter hero-fighter" src="${heroAsset()}" alt="Your adventurer"><span class="shield-shell ${b.shield>0?'charged':''}"></span><span class="battle-vs">${icon('swords')}</span>${monsterPortrait(b.monsterId,'fighter monster-fighter')}<div class="arena-glow"></div><div class="fx-layer" aria-hidden="true"></div></div>
 <p class="battle-log" aria-live="polite">${!b.started?'Ready when you are. Press Start Battle.':esc(b.log)}</p>
 <div class="auto-controls">${b.done?`<button class="primary" id="finishBattle">${b.outcome==='won'?'Collect rewards':'View results'}</button>`:!b.started?'<button class="primary" id="startBattle">Start Battle</button>':`<span class="auto-status"><i></i>${battlePaused?'PAUSED':'FIGHTING'}</span><button id="pauseBattle">${battlePaused?'Resume':'Pause'}</button><button id="battleSpeed" aria-label="Battle speed">${battleSpeed}× speed</button>`}<button id="battleInfo">Battle details</button></div>`;
 $('.run-tools').after(dock);iconsNow();questAudio.mode=b.started&&!b.done?'battle':'board';
 $('#startBattle')?.addEventListener('click',()=>{if(syncIssue)return;state=beginBattle(state);persist();render();});
 $('#pauseBattle')?.addEventListener('click',()=>{battlePaused=!battlePaused;state.run.battlePaused=battlePaused;persist();$('#pauseBattle').textContent=battlePaused?'Resume':'Pause';$('.auto-status').innerHTML='<i></i>'+(battlePaused?'PAUSED':'FIGHTING');if(battlePaused)clearTimeout(battleTimer);else scheduleBattle();});
 $('#battleSpeed')?.addEventListener('click',()=>{battleSpeed=battleSpeed===1?2:1;$('#battleSpeed').textContent=battleSpeed+'× speed';scheduleBattle();});
 $('#battleInfo').onclick=()=>{modal(`<button class="close" data-close aria-label="Close battle details">${icon('x')}</button><h2 id="dialog-title">${b.name}</h2><p>${esc(b.trait||'')}</p><p>Enemy shield: ${b.enemyShield||0} HP</p><p>${weaponAbility(career(state).equipped.sword).description}</p><p>${(b.effects||[]).map(esc).join(' · ')||'Your learned skills trigger during the fight.'}</p>`);};
 if(b.done)battleTimer=setTimeout(completeBattle,1500);else scheduleBattle();$('#finishBattle')?.addEventListener('click',completeBattle);
}
function completeBattle(){clearTimeout(battleTimer);if(syncIssue){showSyncIssue();return;}if(!state.battle?.done)return;state=finishBattle(state);persist();render();if(state.phase==='results')showResults();else if(state.upgradePending)showUpgrade();else closeModal();}
function showEncounter(){
 const kind=state.event,e=EVENTS[kind];if(!e)return;
 if(['treasure','blessing','storm'].includes(kind)){state=resolveEvent(state);persist();render();notify(e.name+' · '+e.description.replaceAll('gold','run tokens'));scheduleJourney();return;}
 if(kind==='camp'){
  const passage=data.verses.find(v=>STAGES[state.stage].chapters.includes(v.chapter));
  modal(`<div class="eyebrow gold">A MOMENT TO PREPARE</div><h2 id="dialog-title">Rest or train?</h2><div class="verse-card"><blockquote>${esc(passage.text)}</blockquote><cite>${esc(passage.reference)}</cite></div><div class="upgrade-grid"><button id="restCamp" class="skill-card"><strong>Rest by the fire</strong><span>Recover 35 HP and 25 ultimate charge.</span></button><button id="trainCamp" class="skill-card"><strong>Strengthen your skills</strong><span>Improve one learned skill. If all skills are mastered, gain +3 attack instead. No healing.</span></button></div>`);
  const choose=choice=>{if(syncIssue)return;state=campChoice(state,choice);persist();closeModal();render();if(state.upgradePending)showUpgrade();};$('#restCamp').onclick=()=>choose('rest');$('#trainCamp').onclick=()=>choose('train');return;
 }
 if(kind==='market'){
  state=enterShop(state);const shop=state.run.shop;
  modal(`<div class="merchant-scene"><div class="merchant-greeting"><span class="eyebrow gold">THE WAYFARER’S EMPORIUM</span><h2 id="dialog-title">A little help for the road.</h2><p>“Choose wisely, traveler. A new skill can turn the tide.”</p></div></div><div class="merchant-catalog"><header><div><span class="eyebrow gold">RUN SHOP</span><h3>Supplies & discoveries</h3></div><strong class="merchant-wallet">${icon('coins')} ${state.tokens}<small>RUN TOKENS</small></strong></header><p class="merchant-note">These upgrades last this run. Your permanent gold stays safe.</p><div class="merchant-stock">${shop.offers.map((offer,i)=>{const sk=offer.id.startsWith('skill:')?SKILLS.find(x=>x.id===offer.desc):null,sold=shop.bought.includes(i);return `<button class="merchant-offer rarity-${sk?.rarity||'common'} ${sold?'sold':''}" data-offer="${i}" ${sold||state.tokens<offer.price?'disabled':''}><span class="offer-icon">${icon(sk?.icon||({heal:'heart-pulse',attack:'sword',defense:'shield'}[offer.id]))}</span><span class="offer-copy"><small>${sk?sk.rarity.toUpperCase()+' · LEVEL '+(skillLevel(state,sk.id)+1):'SUPPLY'}</small><strong>${sk?.name||offer.name}</strong><span>${sk?sk.desc(skillLevel(state,sk.id)+1):offer.desc}</span></span><b>${sold?'SOLD OUT':offer.price+' tokens'}</b></button>`;}).join('')}</div><details class="merchant-build"><summary>Your current skills</summary>${SKILLS.filter(x=>skillLevel(state,x.id)).map(x=>`<p><strong>${x.name} ${skillLevel(state,x.id)}</strong> · ${x.desc(skillLevel(state,x.id))}</p>`).join('')||'<p>No skills yet.</p>'}</details><footer><button id="refreshShop" class="quiet" ${state.tokens<10+shop.refreshes*5?'disabled':''}>Reroll · ${10+shop.refreshes*5} tokens</button><button class="primary" id="leaveShop">Exit shop ${icon('arrow-right')}</button></footer></div>`,true);
  $('.modal').classList.add('merchant-modal');persist();
  document.querySelectorAll('[data-offer]').forEach(b=>b.onclick=()=>{if(syncIssue)return;try{state=buyRunOffer(state,Number(b.dataset.offer));persist();render();showEncounter();}catch(e){notify(e.message);}});
  $('#refreshShop').onclick=()=>{if(syncIssue)return;state=refreshShop(state);persist();render();showEncounter();};

  $('#leaveShop').onclick=()=>{if(syncIssue)return;state={...state,event:null,run:{...state.run,shop:null}};persist();closeModal();render();};return;
 }
 modal(`<div class="encounter-icon">${icon(e.icon)}</div><div class="eyebrow gold">ON YOUR JOURNEY</div><h2 id="dialog-title">${e.name}</h2><p class="muted">${e.description.replaceAll('gold','run tokens')}</p><button class="primary full" id="resolveEncounter">Continue journey ${icon('arrow-right')}</button>`);
 $('#resolveEncounter').onclick=()=>{if(syncIssue)return;state=resolveEvent(state);persist();closeModal();render();};
}
function showUpgrade(){
 if(!state.skillChoices?.length){state.skillChoices=drawSkillChoices(state);persist();}
 const supplies={lanterns:{name:'Light of wisdom',icon:'lamp',description:'One lantern to reveal a clue.'},wards:{name:'Steadfast ward',icon:'shield-check',description:'One ward to protect your gold.'},coins:{name:'Traveler’s tokens',icon:'coins',description:'15 extra run tokens for supplies.'}};
 modal(`<div class="eyebrow gold">${state.rewardReason==='start'?'PREPARE YOUR RUN':state.rewardReason==='battle'?`BATTLE WON · RUN SKILL`:state.rewardReason==='camp'?'CAMP TRAINING · SKILL UPGRADE':'VERSE ANSWERED · RUN SKILL'}</div><h2 id="dialog-title">Choose your next skill.</h2><p class="muted">${state.rewardReason==='camp'?'Improve one of your learned skills.':'Three discoveries. One choice. Shape your adventure.'}</p><div class="upgrade-grid skill-choices">${state.skillChoices.map(id=>{const sk=SKILLS.find(k=>k.id===id),level=skillLevel(state,id);return sk?`<button data-upgrade="${id}" class="skill-card rarity-${sk.rarity}"><span class="rarity-label">${sk.rarity.toUpperCase()}</span><span class="skill-icon">${icon(sk.icon)}</span><strong>${sk.name}</strong><span class="skill-level">${level?`LEVEL ${level} → ${level+1}`:'NEW SKILL · LEVEL 1'}</span><span>${sk.desc(level+1)}</span><span class="choose-label">${level?'Upgrade skill':'Learn skill'} ${icon('arrow-right')}</span></button>`:`<button data-upgrade="${id}" class="skill-card rarity-common"><span class="rarity-label">SUPPLY</span><span class="skill-icon">${icon(supplies[id].icon)}</span><strong>${supplies[id].name}</strong><span>${supplies[id].description}</span><span class="choose-label">Collect</span></button>`;}).join('')}</div><p class="fine">Skills last until this run ends. Permanent equipment stays with your hero. Repeated picks improve skills. Last Light is a one-use revival.</p>`,true);
 document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{if(syncIssue){showSyncIssue();return;}state=chooseUpgrade(state,b.dataset.upgrade);persist();render();chime();closeModal();});
}
function showSkills(){const picked=SKILLS.filter(sk=>skillLevel(state,sk.id));modal(`<button class="close" data-close aria-label="Close skills">${icon('x')}</button><div class="eyebrow gold">YOUR ADVENTURER’S BUILD</div><h2 id="dialog-title">Skills for the journey.</h2><p class="muted">${maxHealth(state)} maximum health · ${state.run?.charge||0}% ultimate charge · ${baseDamage(state,'strike')} base strike damage</p>${picked.length?`<div class="skill-library">${picked.map(sk=>`<article class="rarity-${sk.rarity}"><span class="skill-icon">${icon(sk.icon)}</span><div><h3>${sk.name} <small>LV ${skillLevel(state,sk.id)} / 3</small></h3><p>${sk.desc(skillLevel(state,sk.id))}</p></div></article>`).join('')}</div>`:'<div class="empty"><p>Win a monster battle or answer a Bible trial correctly to choose your first skill.</p></div>'}<p class="fine">New offers are random. Learned skills reset after this run. Your lobby equipment and permanent training persist.</p>`,true);}
async function animateCombat(action){
 if(battleAnimating||battlePaused||!state.battle?.started)return;if(syncIssue){showSyncIssue();return;}
 const before=state,next=combatTurn(state,action),arena=$('.battle-arena');if(!arena)return;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const pause=ms=>new Promise(resolve=>setTimeout(resolve,reduced?10:ms/battleSpeed));
 battleAnimating=true;document.querySelectorAll('[data-combat], .modal .close, .topbar button, .right-rail button, .journey button, .run-tools button, #battleInfo, #roll').forEach(x=>x.disabled=true);
 try{
  $('.battle-log').textContent=action==='guard'?'You raise your shield and brace for the attack…':action==='radiance'?'Your weapon gathers radiant energy…':'You step forward with a sword strike…';
  arena.classList.add('anim-'+action);const layer=$('.fx-layer');
  layer.innerHTML=`${action==='guard'?'<span class="guard-aura"></span>':action==='radiance'?'<span class="radiant-orb"></span>':'<span class="sword-arc"></span>'}`;
  await pause(380);
  arena.classList.add('enemy-hit');
  const turn=next.battle.lastTurn||{},hpDamage=turn.damageDealt??before.battle.hp-next.battle.hp;
  if(turn.lifeStolen)layer.insertAdjacentHTML('beforeend',`<span class="sustain-pop">+${turn.lifeStolen} HP · LIFE STEAL</span>`);
  if(turn.shieldGained){$('.shield-shell').classList.add('charged');layer.insertAdjacentHTML('beforeend',`<span class="aegis-pop">+${turn.shieldGained} SHIELD</span>`);}
  layer.insertAdjacentHTML('beforeend',`<span class="damage-pop enemy-damage">−${hpDamage}</span>${next.battle.burn?`<span class="element-burst fire-burst">${icon('flame')}</span>`:''}${next.battle.effects.includes('Chain lightning')?`<span class="element-burst lightning-burst">${icon('zap')}</span>`:''}${next.battle.poison?'<span class="poison-burst"></span>':''}${next.battle.effects.includes('Critical hit')?'<span class="critical-label">CRITICAL!</span>':''}`);iconsNow();
  const hpText=$('.combat-stats>div:nth-child(2)>span'),hpBar=$('.health-bar.enemy>b');if(hpText)hpText.textContent=`${next.battle.hp} / ${next.battle.max} HP`;if(hpBar)hpBar.style.width=`${next.battle.hp/next.battle.max*100}%`;chime();
  await pause(480);
  if(next.battle.outcome!=='won'){
   arena.classList.remove('enemy-hit');arena.classList.add('enemy-counter');$('.battle-log').textContent=before.battle.intent==='heavy'?`${before.battle.name} unleashes a heavy counterattack!`:`${before.battle.name} strikes back!`;
   await pause(300);arena.classList.add(action==='guard'?'guard-impact':'hero-hit');
   if(turn.shieldBlocked)layer.insertAdjacentHTML('beforeend',`<span class="shield-impact">${turn.shieldBlocked} ABSORBED</span>`);
   const lost=turn.healthDamage??before.health-next.health;layer.insertAdjacentHTML('beforeend',`<span class="damage-pop hero-damage ${lost<=0?'healing':''}">${lost>0?'−':'+'}${Math.abs(lost)}</span>${action==='guard'?'<span class="blocked-label">BLOCKED</span>':''}${skillLevel(before,'frost')?`<span class="frost-burst">${icon('snowflake')}</span>`:''}`);iconsNow();
   const heroText=$('.combat-stats>div:first-child>span'),heroBar=$('.health-bar:not(.enemy)>b');if(heroText)heroText.textContent=`${next.health} / ${maxHealth(next)} HP`;if(heroBar)heroBar.style.width=`${next.health/maxHealth(next)*100}%`;
   await pause(430);
  }else{arena.classList.add('victory-flash');await pause(330);}
  next.run.battlePaused=state.run.battlePaused;state=next;battleAnimating=false;persist();render();
 }catch(e){battleAnimating=false;next.run.battlePaused=state.run.battlePaused;state=next;persist();render();notify('The turn is complete.');}
}

function showFeedback(){const f=state.feedback;if(!f)return;
 modal(`<div class="feedback-icon ${f.correct?'success':'retry'}">${icon(f.correct?'check':'book-open')}</div><div class="eyebrow gold">SCRIPTURE TRIAL</div><h2 id="dialog-title">${f.correct?'The path grows brighter.':'A verse to revisit.'}</h2><div class="answer-card"><small>EXPECTED ANSWER</small><p>${esc(f.answer)}</p><strong>${esc(f.reference)}</strong></div>${!f.correct?`<p>Your answer: ${esc(f.input||'Skipped')}</p>`:''}<p class="fine">${state.stageCorrect} correct this run. Win with at least 4 correct to earn this chapter’s Armor of God milestone.</p><button class="primary full" id="continue">${f.correct?'Choose a run skill':'Continue journey'}</button>`);
 $('#continue').onclick=()=>{if(syncIssue)return;state.pending=null;state.feedback=null;if(f.correct){state.upgradePending=true;state.rewardReason='verse';state.skillChoices=drawSkillChoices(state);persist();render();showUpgrade();}else{persist();closeModal();render();}};
}
function showResults(){const stats=summary(state),missed=state.attempts.filter(a=>!a.correct),p=state.run?.payout;
 modal(`<button class="close" data-close aria-label="Close results">${icon('x')}</button><div class="eyebrow gold">${p?'RUN COMPLETE':'ADVENTURE JOURNAL'}</div><h2 id="dialog-title">${p?.outcome==='victory'?'Chapter conquered.':p?.outcome==='defeat'?'Rise stronger next time.':'Your journey so far.'}</h2>${p?`<div class="armory-wallet"><span>+${p.gold} gold</span><span>+${p.xp} hero XP</span><span>+${p.ore} forge shards</span><span>+${p.chests} chests</span></div><p class="notice">Rewards are already in your permanent inventory.${p.armor?' Armor earned: '+p.armor+'.':''}</p>`:''}<div class="results-stats"><div><b>${stats.right}</b><span>Correct</span></div><div><b>${stats.wrong}</b><span>Incorrect</span></div><div><b>${stats.accuracy}%</b><span>Accuracy</span></div></div><p>${state.battlesWon} battles won · ${state.run?.turn||0} / 30 turns. Battles never count as wrong Bible answers.</p><div class="results-actions">${state.phase==='run'?'<button class="quiet" id="retireRun">End this run & collect rewards</button>':'<button class="primary" id="returnLobby">Return to character lobby</button>'}${missed.length?'<button class="quiet" id="practiceMissed">Practice missed verses</button>':''}<button class="quiet" id="download">Download results</button></div><h3>Verses to revisit · ${missed.length}</h3>${missed.length?`<div class="review-list">${missed.map(a=>`<article><div class="review-ref">${esc(a.reference)}</div><p>${esc(a.prompt)}</p><div class="review-answer">Your answer: ${esc(a.input||'Skipped')}</div><div class="review-answer">Correct answer: ${esc(a.answer)}</div></article>`).join('')}</div>`:'<p>No missed verses in this run.</p>'}`,true);
 $('#returnLobby')?.addEventListener('click',()=>{state=returnToLobby(state);persist();closeModal();render();});
 $('#retireRun')?.addEventListener('click',()=>{modal(`<h2 id="dialog-title">End this attempt?</h2><p>Collect rewards earned so far. Temporary skills and tokens end with this run.</p><button class="primary full" id="confirmRetire">End run & collect</button><button class="quiet full" id="keepRun">Keep playing</button>`);$('#keepRun').onclick=()=>{closeModal();continueRun();};$('#confirmRetire').onclick=()=>{if(syncIssue)return;clearTimeout(journeyTimer);state=settleRun(state,'retired');persist();render();showResults();};});
 $('#practiceMissed')?.addEventListener('click',()=>{practice={items:missed,index:0,right:0};showReviewPractice();});$('#download').onclick=downloadResults;
}
function showReviewPractice(){if(practice.index>=practice.items.length){modal(`<div class="feedback-icon success">${icon('check')}</div><h2 id="dialog-title">Review complete.</h2><p>You answered ${practice.right} of ${practice.items.length} correctly during review.</p><button class="primary full" id="backResults">Back to results</button>`);$('#backResults').onclick=showResults;return;}const q=practice.items[practice.index];modal(`<button class="close" data-close aria-label="Close practice">${icon('x')}</button><div class="eyebrow gold">REVIEW ${practice.index+1} / ${practice.items.length}</div><h2 id="dialog-title">Try this one again.</h2><div class="verse-card"><blockquote>${esc(q.prompt)}</blockquote>${q.mode==='blank'?`<cite>${esc(q.reference)}</cite>`:''}</div><form id="reviewForm"><label>Your answer<textarea name="answer" rows="3" required></textarea></label><button class="primary full">Check answer</button></form><div id="reviewFeedback" role="status"></div>`);$('#reviewForm').onsubmit=e=>{e.preventDefault();const correct=grade(q,new FormData(e.target).get('answer'));if(correct)practice.right++;$('#reviewForm').hidden=true;$('#reviewFeedback').innerHTML=`<p class="${correct?'teal':'gold'}">${correct?'Correct!':'Keep practicing.'}</p><div class="answer-card"><p>${esc(q.answer)}</p><strong>${esc(q.reference)}</strong></div><button class="primary full" id="nextReview">Next</button>`;$('#nextReview').onclick=()=>{practice.index++;showReviewPractice();};};}
function downloadResults(){const s=summary(state);const text=[`Bible Flashcard Game — ${state.alias||state.name}`,`Correct: ${s.right} | Incorrect: ${s.wrong} | Accuracy: ${s.accuracy}%`,`Battles won: ${state.battlesWon} | Defeats: ${state.battlesLost}`,`Skills: ${SKILLS.filter(sk=>skillLevel(state,sk.id)).map(sk=>sk.name+' Lv '+skillLevel(state,sk.id)).join(', ')||'None'}`,`Armor: ${state.armor.map(i=>STAGES[i].armor).join(', ')||'None yet'}`,'',...state.attempts.map((a,i)=>`${i+1}. ${a.correct?'CORRECT':'INCORRECT'} — ${a.reference}\n${a.prompt}\nYour answer: ${a.input||'Skipped'}\nExpected: ${a.answer}\nLantern clue used: ${a.assisted?'Yes':'No'}\n`) ].join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));link.download='armor-quest-results.txt';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);}
function showLibrary(){modal(`<button class="close" data-close aria-label="Close library">${icon('x')}</button><div class="eyebrow gold">READ · REMEMBER · RETURN</div><h2 id="dialog-title">The verse library.</h2><p class="muted">The ${data.verses.length} memory passages quoted in your study sets. Read them here before trying a recall trial.</p><label>Chapter<select id="chapterFilter"><option value="all">All chapters</option>${[1,2,3,4].map(i=>`<option value="${i}">John ${i}</option>`).join('')}</select></label><div id="libraryList" class="library-list"></div><p class="fine">Verse wording comes from the supplied documents. Their quiz directions are used only as question content.</p>`,true);const update=()=>{$('#libraryList').innerHTML=data.verses.filter(v=>$('#chapterFilter').value==='all'||v.chapter===Number($('#chapterFilter').value)).map(v=>`<article><h3>${esc(v.reference)}</h3><p>${esc(v.text)}</p></article>`).join('');};$('#chapterFilter').onchange=update;update();}
function showHelp(){modal(`<button class="close" data-close aria-label="Close help">${icon('x')}</button><h2 id="dialog-title">Build. Journey. Grow.</h2><ol class="howto"><li><strong>Prepare in the lobby.</strong> Choose your appearance and combat path. Equip gear, combine duplicates, and spend earned gold on permanent stats.</li><li><strong>Enter a chapter.</strong> Your hero automatically travels through a 30-turn board run. Pause or resume whenever you need.</li><li><strong>Build during the run.</strong> Battles play automatically. Choose random skills, answer Bible trials, and buy temporary upgrades with run tokens. Elite encounters arrive every 10 turns, with the final boss on turn 30.</li><li><strong>Win or fall.</strong> Defeat ends the attempt. Both outcomes award gold and earned equipment resources. Return to the lobby, upgrade, and try again. Only an acquired one-use revive can rescue a fallen hero.</li><li><strong>Earn the Armor of God.</strong> Win a chapter with at least four correct Bible answers for its armor milestone. You can replay unlocked chapters and review every missed verse.</li></ol>`,true);}
function showProfile(){modal(`<button class="close" data-close aria-label="Close profile">${icon('x')}</button><div class="eyebrow gold">YOUR ADVENTURER</div><h2 id="dialog-title">${esc(state.alias||state.name)}</h2><form id="profileForm">${characterPicker(state.character)}<label>Your name<input name="name" value="${esc(state.name)}" maxlength="40" required></label><label>Hero alias<input name="alias" value="${esc(state.alias)}" maxlength="30"></label><label>Challenge style<select name="mode">${Object.entries(MODES).map(([k,v])=>`<option value="${k}" ${k===state.mode?'selected':''}>${v}</option>`).join('')}</select></label><p class="fine">Style changes apply to your next roll. ${guest?'Practice progress is saved on this device.':'Your progress is saved to your account.'}</p><button class="primary full">Save hero</button></form><button class="text-button full" id="signout">${guest?'Leave practice':'Sign out'}</button>`);$('#profileForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.name=f.get('name').trim();state.alias=f.get('alias').trim();state.mode=f.get('mode');state.character=f.get('character')==='female'?'female':'male';persist();closeModal();render();};$('#signout').onclick=async()=>{await saveChain;if(syncIssue){showSyncIssue();return;}if(client&&user){const {error}=await client.auth.signOut();if(error){notify(error.message);return;}}welcome=true;user=null;guest=false;state=freshState();revision=0;closeModal();render();};}
function showSyncIssue(){modal(`<h2 id="dialog-title">Your progress needs attention.</h2><p>Keep this page open. You can retry saving, or load the latest saved quest from your account. Loading replaces the progress currently shown here.</p><button class="primary full" id="retrySave">Retry saving this quest</button><button class="quiet full" id="reloadCloud">Load latest saved quest</button><button class="text-button full" id="exportBeforeSync">Download current results</button><p id="syncError" role="status"></p>`);$('#exportBeforeSync').onclick=downloadResults;$('#retrySave').onclick=async()=>{syncIssue=false;await persist();if(!syncIssue){closeModal();render();}else $('#syncError').textContent='Saving failed. If another device has newer progress, load the latest saved quest.';};$('#reloadCloud').onclick=async()=>{try{await enterAccount(user);closeModal();render();}catch(e){$('#syncError').textContent=e.message;}};}
function savedGame(){try{const saved=JSON.parse(localStorage.getItem('armorQuestPracticeV2')||'null');return saved?.schema===2?migrate(saved):null;}catch{return null;}}
function renderWelcome(){
 clearTimeout(journeyTimer);clearTimeout(battleTimer);document.body.dataset.phase='welcome';questAudio.mode='board';
 const saved=savedGame();
 $('#app').innerHTML=`<main class="welcome-screen" style="background-image:linear-gradient(90deg,rgba(6,17,29,.87),rgba(6,17,29,.65)),url('${import.meta.env.BASE_URL}board-art.png')"><div class="welcome-content"><div class="eyebrow gold">BIBLE FLASHCARD GAME · JOHN 1–4</div><div class="welcome-emblem">${icon('shield')}</div><h1>The Armor Quest</h1><p class="welcome-tagline">Your faith. Your adventure.</p><p>Brave the board. Master the Word.<br>Build a hero worthy of the armor.</p><div class="welcome-actions"><button id="newGame" class="primary full">${icon('sparkles')} New Game ${icon('arrow-right')}</button><button id="continueGame" class="quiet full" ${!saved&&!configured?'disabled':''}>${icon('flag')} Continue Saved Game</button></div><p class="welcome-save">${saved?`${esc(saved.alias||saved.name)} · Level ${career(saved).level} · Chapter ${saved.stage+1}<br>Your saved adventure is ready when you are.`:'No saved game on this device yet.'}</p>${configured?'<button id="welcomeSignIn" class="text-button">Sign in to an online saved game</button>':''}<small>THE ARMOR OF GOD · EPHESIANS 6:10–17</small></div></main>`;
 iconsNow();$('#newGame').onclick=showPracticeSetup;
 $('#continueGame').onclick=()=>{const saved=savedGame();if(!saved){if(configured)showAuth('login');return;}state=saved;guest=true;user=null;welcome=false;render();continueRun();};
 $('#welcomeSignIn')?.addEventListener('click',()=>showAuth('login'));
}
render();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_quest_progress',description:'Read current chapter, earned armor and answer counts for the visible quest.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:(input)=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected an empty object.');return {chapter:state.stage+1,armor:state.armor.map(i=>STAGES[i].armor),...summary(state),practice:guest,battlesWon:state.battlesWon,skills:state.skills};}});}catch{}}
function applyGrowth(action,message){if(syncIssue){showSyncIssue();return false;}try{state=action(state);state.health=Math.min(state.health,maxHealth(state));state.focus=Math.min(state.focus,maxFocus(state));persist();render();if(message)notify(message);return true;}catch(e){notify(e.message);return false;}}
function statLine(stats){return [['attack','ATK'],['hp','HP'],['defense','DEF']].filter(([k])=>stats[k]).map(([k,n])=>`+${stats[k]} ${n}`).join(' · ')||'No bonus';}
function scheduleJourney(){clearTimeout(journeyTimer);if(welcome||state.phase!=='run'||state.run.paused||busy||syncIssue||document.hidden||$('#overlay').children.length||state.pending||state.event||state.battle||state.upgradePending)return;journeyTimer=setTimeout(()=>roll(),850);}
function toggleJourney(){if(state.phase!=='run')return;state.run.paused=!state.run.paused;persist();render();if(!state.run.paused)continueRun();}
function continueRun(){if(welcome||state.phase!=='run')return;if(state.battle)showBattle();else if(state.pending)showChallenge();else if(state.upgradePending)showUpgrade();else if(state.event)showEncounter();else scheduleJourney();}
function renderLobby(){
 document.body.dataset.phase='lobby';
 clearTimeout(journeyTimer);clearTimeout(battleTimer);questAudio.mode='board';
 const c=career(state),g=gearStats(state),name=state.alias||state.name||'Your next legend',path=PATHS.find(x=>x.id===state.path)||PATHS[0],latest=state.run?.payout;
 $('#app').innerHTML=`<header class="topbar"><a href="./" class="brand"><span class="brand-emblem">${icon('shield')}</span><span>THE ARMOR QUEST<small>BIBLE FLASHCARD GAME</small></span></a><nav aria-label="Main navigation"><button id="versesNav">${icon('book-open')} Verse library</button><button id="resultsNav">${icon('scroll-text')} My results</button><button id="monstersNav" aria-label="Monster collection">${icon('swords')} Monsters</button></nav><button id="profile" class="profile">${icon('crown')} ${esc(state.alias||state.name||'Create your hero')}</button></header><main class="lobby-main"><div class="quest-heading"><div><div class="eyebrow">YOUR LEGEND STARTS HERE</div><h1>Rise. Return. Grow stronger.</h1><p>Build your hero. Brave the board. Carry the Word.</p></div><button id="help" class="quiet">${icon('circle-help')} How to play</button></div><div class="lobby-grid"><section class="hero-sanctuary"><div class="lobby-scene"><div class="lobby-halo"></div><div class="hero-title"><span class="eyebrow gold">LEVEL ${c.level} · ${path.name.toUpperCase()}</span><h2>${esc(name)}</h2></div><img class="lobby-hero" src="${heroAsset()}" alt="Your ${state.character} adventurer"><div class="lobby-gear">${SLOTS.map(slot=>{const key=c.equipped[slot.id];return `<button data-lobby-slot="${slot.id}" class="equipment-slot ${key?'gear-rarity-'+itemInfo(key).rarity:''}">${icon(slot.icon)}<small>${slot.name}</small><b>${key?'Lv '+(c.slotLevels[slot.id]||1):'Empty'}</b></button>`;}).join('')}</div><div class="lobby-stats"><span>${icon('sword')}<b>${baseDamage(state,'strike')}</b> Attack</span><span>${icon('heart')}<b>${maxHealth(state)}</b> Health</span><span>${icon('shield')}<b>${g.defense}</b> Defense</span></div></div><div class="lobby-wallet"><span>${icon('coins')} <b>${state.coins}</b> permanent gold</span><span>${icon('gem')} ${c.ore} shards</span><button id="sound" class="icon-button" aria-label="${sound?'Mute':'Enable'} music">${icon(sound?'volume-2':'volume-x')}</button></div><div class="lobby-actions"><button id="armory" class="quiet">${icon('shirt')} Equipment & forge</button><button id="training" class="quiet">${icon('arrow-up-right')} Upgrade stats</button><button id="lobbyShop" class="quiet">${icon('store')} Equipment shop</button></div></section><aside class="lobby-prepare panel"><div class="panel-label">PREPARE YOUR NEXT RUN</div><h2>A path of your own.</h2><p class="muted">Both appearances can choose any combat path. Your path’s second ability unlocks at hero level 5.</p><div class="path-choices">${PATHS.map(p=>`<button data-path="${p.id}" class="${state.path===p.id?'selected':''}" ${state.phase==='results'?'disabled':''}>${icon(p.icon)}<span><strong>${p.name}</strong><small>${p.desc}</small></span>${state.path===p.id?icon('check'):''}</button>`).join('')}</div><label>Choose chapter<select id="chapterSelect" ${state.phase==='results'?'disabled':''}>${STAGES.map((a,i)=>`<option value="${i}" ${i===state.stage?'selected':''} ${i>state.unlocked?'disabled':''}>${i+1}. ${a.name}${i>state.unlocked?' · Locked':''}</option>`).join('')}</select></label><div class="chapter-brief"><span>${icon('dices')} 30 turns</span><span>${icon('swords')} Automatic battles</span><span>${icon('book-open')} Bible trials</span></div><button id="startRun" class="primary full">${icon(state.phase==='results'?'scroll-text':'flag')} ${state.phase==='results'?'View run rewards':user||guest?'Enter the board':'Create hero & begin'} ${icon('arrow-right')}</button><p class="fine">Your hero moves automatically. Pause for skills, shops and Bible answers. Win or fall, then return here with gold for permanent upgrades.</p><button class="sync" id="sync">${guest?'Practice saved on this device':user?'Online account':'Sign in for cross-device progress'}</button>${latest?`<div class="last-run"><span class="eyebrow">LAST RUN · ${latest.outcome.toUpperCase()}</span><strong>+${latest.gold} gold earned</strong><button id="lastResults" class="text-button">Review run & missed verses ${icon('arrow-right')}</button></div>`:''}</aside></div><div class="lobby-milestones panel"><span class="eyebrow gold">THE ARMOR OF GOD</span><div>${STAGES.map((a,i)=>`<span class="${state.armor.includes(i)?'earned':''}">${icon(a.icon)}<strong>${a.armor}</strong><small>${state.armor.includes(i)?'Earned':'Win chapter '+(i+1)+' with 4 correct answers'}</small></span>`).join('')}</div></div></main>`;
 iconsNow();const ready=fn=>()=>{if(!user&&!guest){showAuth();return;}if(state.phase==='results'){state=returnToLobby(state);persist();render();}fn();};
 $('#monstersNav').onclick=showBestiary;$('#profile').onclick=()=>user||guest?showProfile():showAuth();$('#help').onclick=showHelp;$('#versesNav').onclick=showLibrary;$('#resultsNav').onclick=showResults;$('#lastResults')?.addEventListener('click',showResults);
 $('#sound').onclick=()=>{sound=!sound;questAudio.enabled=sound;questAudio.start();render();};
 $('#armory').onclick=ready(()=>showArmory());$('#training').onclick=ready(showTraining);$('#lobbyShop').onclick=ready(showLobbyShop);
 document.querySelectorAll('[data-lobby-slot]').forEach(b=>b.onclick=ready(()=>showSlot(b.dataset.lobbySlot)));
 document.querySelectorAll('[data-path]').forEach(b=>b.onclick=()=>{if(state.phase!=='lobby')return;state.path=b.dataset.path;persist();render();});
 $('#chapterSelect').onchange=e=>{state.stage=Number(e.target.value);persist();render();};
 $('#startRun').onclick=()=>{if(state.phase==='results'){showResults();return;}if(!user&&!guest){showAuth();return;}if(syncIssue){showSyncIssue();return;}state=startRun(state);persist();render();showUpgrade();};
 $('#sync').onclick=()=>syncIssue?showSyncIssue():!user?showAuth():notify('Progress saves at every encounter boundary.');
}
function showTraining(){modal(`<button class="close" data-close aria-label="Close training">${icon('x')}</button><div class="eyebrow gold">PERMANENT CHARACTER GROWTH</div><h2 id="dialog-title">Invest in your next victory.</h2><p>${state.coins} gold available. These upgrades apply to every future run.</p><div class="talent-grid">${TALENTS.map(t=>`<article>${icon(t.icon)}<h3>${t.name}</h3><strong>Rank ${career(state).talents[t.id]||0}</strong><p>${t.desc.replace('point','rank')}</p><button class="primary" data-gold-train="${t.id}" ${state.coins<trainingCost(state,t.id)?'disabled':''}>Upgrade · ${trainingCost(state,t.id)} gold</button></article>`).join('')}</div><p class="fine">Hero XP also raises your level and awards talent points in the Armory.</p>`,true);document.querySelectorAll('[data-gold-train]').forEach(b=>b.onclick=()=>{if(applyGrowth(s=>trainWithGold(s,b.dataset.goldTrain),'Permanent stat increased.'))showTraining();});}
function showLobbyShop(){modal(`<button class="close" data-close aria-label="Close shop">${icon('x')}</button><div class="eyebrow gold">PERMANENT EQUIPMENT SHOP</div><h2 id="dialog-title">Build your collection.</h2><p>${state.coins} gold · Each purchase gives the exact Common piece shown. Collect duplicates to fuse in the forge.</p><label>Equipment set<select id="shopSet">${SETS.map(x=>`<option value="${x.id}">${x.name} · ${x.desc}</option>`).join('')}</select></label><div class="gear-grid">${SLOTS.map(x=>`<button class="gear-card" data-buy-gear="${x.id}" ${state.coins<60?'disabled':''}>${icon(x.icon)}<strong>${x.name}</strong><span>Common · 60 gold</span></button>`).join('')}</div><p class="fine">All currency is earned by playing. Gear persists across runs.</p>`,true);document.querySelectorAll('[data-buy-gear]').forEach(b=>b.onclick=()=>{const set=$('#shopSet').value;if(applyGrowth(s=>buyLobbyItem(s,b.dataset.buyGear,set),'Equipment added to your collection.'))showLobbyShop();});}
function showArmory(tab='equipment'){
 const c=career(state),g=gearStats(state),locked=state.phase==='run',xp=xpNeeded(c.level);
 modal(`<button class="close" data-close aria-label="Close armory">${icon('x')}</button><div class="eyebrow gold">YOUR GROWING LEGEND · QUEST ${c.runs+1}</div><h2 id="dialog-title">The Armory</h2><div class="armory-hero"><img src="${heroAsset()}" alt="Your ${state.character||'male'} adventurer"><div><h3>${esc(state.alias||state.name)}</h3><strong>LEVEL ${c.level}${c.points?` · ${c.points} talent ${c.points===1?'point':'points'} ready`:''}</strong><div class="progress-bar"><span style="width:${c.level===50?100:c.xp/xp*100}%"></span></div><small>${c.level===50?'Maximum hero level':`${c.xp} / ${xp} XP to level ${c.level+1}`}</small><div class="hero-stat-grid"><span>${icon('sword')}<b>${baseDamage(state,'strike')}</b> Attack</span><span>${icon('heart')}<b>${maxHealth(state)}</b> Max HP</span><span>${icon('shield')}<b>${g.defense+skillLevel(state,'frost')*2}</b> Defense</span></div></div></div><div class="armory-wallet"><span>${icon('coins')} ${state.coins} gold</span><span>${icon('gem')} ${c.ore} forge shards</span><span>${icon('gem')} ${c.chests} chests</span></div>${locked?'<div class="notice">Finish this run before changing permanent equipment.</div>':''}<div class="tabs armory-tabs">${['equipment','forge','talents'].map(t=>`<button data-armory-tab="${t}" class="${t===tab?'selected':''}">${t==='equipment'?'Equipment':t==='forge'?'Chests & forge':'Talents'}${t==='talents'&&c.points?' •':''}</button>`).join('')}</div>
 ${tab==='equipment'?`<div class="equipment-slots">${SLOTS.map(slot=>{const key=c.equipped[slot.id],item=key?itemInfo(key):null;return `<button data-slot="${slot.id}" class="equipment-slot ${item?'gear-rarity-'+item.rarity:''}"><span>${icon(slot.icon)}</span><strong>${slot.name}</strong><small>${item?`${item.family.name} · ${RARITIES[item.rarity]}`:'Empty slot'}</small><b>${item?'Lv '+(c.slotLevels[slot.id]||1):'Equip gear'}</b></button>`;}).join('')}</div><h3>Set bonuses</h3><div class="set-bonuses">${SETS.map(set=>`<div class="${g.sets[set.id]>=3?'active':''}"><strong>${set.name} <b>${g.sets[set.id]||0}/6</b></strong><span>${set.desc}</span></div>`).join('')}</div><h3>Equipment collection</h3>${inventoryCards(c,null,locked)}`:
 tab==='forge'?`<div class="forge-chest"><span class="forge-emblem">${icon('gem')}</span><h3>A discovery awaits.</h3><p>Choose the slot and set you want to build. Each earned chest gives one piece: 80% Common, 20% Rare.</p><div class="field-row"><label>Equipment slot<select id="chestSlot">${SLOTS.map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}</select></label><label>Armor set<select id="chestSet">${SETS.map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}</select></label></div><button class="primary full" id="openChest" ${locked||!c.chests?'disabled':''}>Open earned chest · ${c.chests} available</button><p class="fine">Start with one chest. Earn chests during runs; rewards settle at victory or defeat.</p></div><h3>Combine matching equipment</h3><p class="muted">Early fusion uses three exact pieces. Epic and higher use fusion subtiers, same-slot materials and exact duplicate breakthroughs. Inspect a piece for its recipe. Slot levels are kept.</p><div class="rarity-ladder">${RARITIES.map((r,i)=>`<span class="gear-rarity-${i}">${r}</span>`).join('<b>›</b>')}</div>${inventoryCards(c,null,locked,true)}`:
 `<p class="muted">Each level gives +1 attack, +5 maximum HP and one talent point. Spend your points to shape your hero.</p><div class="talent-grid">${TALENTS.map(t=>`<article><span>${icon(t.icon)}</span><h3>${t.name}</h3><strong>Rank ${c.talents[t.id]||0}</strong><p>${t.desc}</p><button class="quiet" data-train="${t.id}" ${locked||!c.points?'disabled':''}>Train · 1 point</button></article>`).join('')}</div><p class="notice">Hero levels, talents, equipment, gold and forge shards carry into your next quest. Temporary battle skills start fresh.</p>`}<p class="fine">Bible mastery earns the six Armor of God milestones. Equipment upgrades strengthen your hero in battles. Defense reduces incoming damage by up to 75% before guarding.</p>`,true);
 document.querySelectorAll('[data-armory-tab]').forEach(b=>b.onclick=()=>showArmory(b.dataset.armoryTab));
 document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>showEquipment(b.dataset.item,tab));
 document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>showSlot(b.dataset.slot));
 document.querySelectorAll('[data-train]').forEach(b=>b.onclick=()=>{if(applyGrowth(s=>trainTalent(s,b.dataset.train),'Talent strengthened.'))showArmory('talents');});
 $('#openChest')?.addEventListener('click',()=>{const slot=$('#chestSlot').value,set=$('#chestSet').value;if(applyGrowth(s=>openChest(s,slot,set))){showEquipment(state.lastLoot,'forge',true);chime();}});
}
function inventoryCards(c,slot,locked,combineOnly=false){const items=Object.entries(c.inventory).filter(([key,count])=>count>0&&(!slot||itemInfo(key).slot===slot)).sort((a,b)=>itemInfo(b[0]).rarity-itemInfo(a[0]).rarity);return items.length?`<div class="gear-grid">${items.map(([key,count])=>{const item=itemInfo(key);return `<button class="gear-card gear-rarity-${item.rarity}" data-item="${key}"><span>${icon(item.spec.icon)}</span><strong>${item.name}</strong><small>${rarityLabel(key)} · Lv ${c.slotLevels[item.slot]||1}</small><b>×${count} ${c.equipped[item.slot]===key?'· Equipped':''}</b><span class="gear-stat">${statLine(itemStats(key,c.slotLevels[item.slot]||1))}</span>${fusionRecipe(state,key).ready?'<em>Fusion ready</em>':combineOnly?'<em>View fusion recipe</em>':''}</button>`;}).join('')}</div>`:'<div class="empty"><p>No equipment here yet. Open your starter chest in Chests & forge.</p></div>';}
function showSlot(slot){const c=career(state),spec=SLOTS.find(s=>s.id===slot);modal(`<button class="close" data-close aria-label="Close equipment">${icon('x')}</button><div class="eyebrow gold">EQUIPMENT SLOT</div><h2 id="dialog-title">${spec.name}</h2>${inventoryCards(c,slot,false)}<button class="text-button full" id="backArmory">Back to Armory</button>`,true);document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>showEquipment(b.dataset.item));$('#backArmory').onclick=()=>showArmory();}
function showEquipment(key,back='equipment',discovered=false){
 const c=career(state),item=itemInfo(key),count=c.inventory[key]||0,level=c.slotLevels[item.slot]||1,cost=upgradeCost(state,item.slot),equipped=c.equipped[item.slot]===key,locked=state.phase==='run',cap=(item.rarity+1)*5,recipe=fusionRecipe(state,key),protectedItem=c.protected?.[key];
 modal(`<button class="close" data-close aria-label="Close equipment details">${icon('x')}</button><div class="eyebrow gold">${discovered?'EQUIPMENT DISCOVERED':'EQUIPMENT DETAILS'}</div><div class="item-display gear-rarity-${item.rarity}">${icon(item.spec.icon)}</div><h2 id="dialog-title">${item.name}</h2><p class="muted">${rarityLabel(key)} · Slot level ${level} · ${count} owned${equipped?' · Equipped':''}</p><div class="item-stats">${statLine(itemStats(key,level))}</div><p class="notice">${item.family.desc}</p>${item.slot==='sword'?`<div class="notice"><strong>${weaponAbility(key).name}</strong><p>${weaponAbility(key).description}</p></div>`:''}<div class="equipment-actions"><button class="primary" id="equipGear" ${locked||equipped||!count?'disabled':''}>${equipped?'Equipped':'Equip this piece'}</button><button class="quiet" id="upgradeGear" ${locked||!equipped||level>=cap||state.coins<cost.gold||c.ore<cost.ore?'disabled':''}>${level>=cap?'Rarity level limit reached':`Level ${level} → ${level+1} · ${cost.gold} gold + ${cost.ore} shards`}</button></div><p class="fine">${level<cap?'Next level: '+statLine(itemStats(key,level+1))+'. ':''}Slot levels transfer when you swap or fuse equipment.</p><button id="resetGear" class="quiet full" ${locked||level===1?'disabled':''}>Reset slot to level 1 · refund all level-up gold and shards</button><button id="protectGear" class="text-button full" ${locked?'disabled':''}>${protectedItem?'Unprotect this item':'Protect this item from fusion'}</button><div class="combine-preview"><h3>${recipe.key?'Fuse into '+rarityLabel(recipe.key):'Maximum fusion tier'}</h3><p>${recipe.description}</p>${recipe.key?`<strong>${statLine(itemStats(key,level))} → ${statLine(itemStats(recipe.key,level))}</strong><p class="fine">${recipe.ready?'Will consume: '+recipe.ingredients.map(k=>rarityLabel(k)+' '+itemInfo(k).name).join(' + '):protectedItem?'Unprotect the base item before fusion.':recipe.missing+' additional eligible material pieces needed.'}${equipped?' This selected equipped base becomes the upgraded result.':''} Other equipped items and protected items are excluded as materials. Slot level ${level} is retained.</p><button class="primary full" id="combineGear" ${locked||!recipe.ready?'disabled':''}>Fuse the displayed recipe</button>`:''}</div><button class="text-button full" id="backArmory">Back to Armory</button>`,true);
 $('#equipGear').onclick=()=>{if(applyGrowth(s=>equipItem(s,key),'Equipment applied.'))showEquipment(key,back);};
 $('#upgradeGear').onclick=()=>{if(applyGrowth(s=>upgradeEquipment(s,item.slot),'Equipment leveled up.'))showEquipment(key,back);};
 $('#resetGear').onclick=()=>{if(applyGrowth(s=>resetEquipmentLevel(s,item.slot),'Level investment refunded.'))showEquipment(key,back);};
 $('#protectGear').onclick=()=>{if(applyGrowth(s=>protectEquipment(s,key)))showEquipment(key,back);};
 $('#combineGear')?.addEventListener('click',()=>{if(applyGrowth(s=>fuseEquipment(s,key),'Equipment fused.')){showEquipment(recipe.key,back,true);chime();}});$('#backArmory').onclick=()=>showArmory(back);
}

